class BinaryCrossEntropy : public XlaNode {
 public:
  static torch::lazy::OpKind ClassOpKind() {
    return torch::lazy::OpKind(at::aten::binary_cross_entropy);
  }

  BinaryCrossEntropy(const torch::lazy::Value& self,
                     const torch::lazy::Value& target,
                     const c10::optional<torch::lazy::Value>& weight,
                     const int64_t& reduction,
                     std::vector<torch::lazy::Shape>&& shapes)
      : XlaNode(torch::lazy::OpKind(at::aten::binary_cross_entropy),
                {self, target, weight.value_or(kNullValue)}, std::move(shapes),
                [&]() {
                  return BinaryCrossEntropyOutputShape(self, target, weight,
                                                       reduction);
                },
                /* num_outputs */ 1, torch::lazy::MHash(reduction)),
        reduction(reduction) {
    has_weight = !!weight;
  }

  std::string ToString() const override {
    std::stringstream ss;
    ss << XlaNode::ToString();
    ss << ", reduction=" << reduction;
    return ss.str();
  }

  bool CanBeReused(const torch::lazy::Value& self,
                   const torch::lazy::Value& target,
                   const c10::optional<torch::lazy::Value>& weight,
                   const int64_t& reduction) const {
    return false;
  }

  torch_xla::XlaOpVector Lower(LoweringContext* loctx) const override;

  int64_t reduction;
  bool has_weight : 1;
};

