    const at::Tensor& self, const at::Tensor& target,
    const c10::optional<at::Tensor>& weight, int64_t reduction) {
  XLA_FN_COUNTER("xla::");
  auto common_device = torch_xla::bridge::GetXlaDevice(self, target, weight);
  TORCH_INTERNAL_ASSERT(common_device);

  torch_xla::XLATensorPtr lazy_self =
      torch_xla::bridge::GetXlaTensorOrCreateForWrappedNumber(self,
                                                              *common_device);
  torch_xla::XLATensorPtr lazy_target =
      torch_xla::bridge::GetXlaTensorOrCreateForWrappedNumber(target,
                                                              *common_device);
  torch_xla::XLATensorPtr lazy_weight =
      torch_xla::bridge::TryGetXlaTensor(weight.value_or(at::Tensor()));
  torch::lazy::NodePtr node = torch::lazy::ReuseNode<BinaryCrossEntropy>(
      lazy_self->GetIrValue(), lazy_target->GetIrValue(),
      lazy_weight ? c10::make_optional(lazy_weight->GetIrValue())
                  : c10::nullopt,
      reduction);
  if (!node) {
    auto shapes = torch::lazy::compute_shape_binary_cross_entropy(
        self, target, weight, reduction);
    TORCH_INTERNAL_ASSERT(shapes.size() == 1);
    if (torch::lazy::symbolicShapeEnabled()) {
      std::vector<torch::jit::IValue> inputs = {self, target, weight,
                                                reduction};
      const char* schema_str =
          "aten::binary_cross_entropy(Tensor self, Tensor target, Tensor? "
          "weight=None, int reduction=Mean) -> Tensor";
      applySymbolicShapesOnLT(schema_str, inputs, shapes);
    }

    node = torch::lazy::MakeNode<BinaryCrossEntropy>(
        lazy_self->GetIrValue(), lazy_target->GetIrValue(),
        lazy_weight ? c10::make_optional(lazy_weight->GetIrValue())
                    : c10::nullopt,
        reduction, std::move(shapes));
    CacheNode(node);
  }

  auto result = torch_xla::bridge::AtenFromXlaTensor(
      torch_xla::XLATensor::Create(std::move(node), *common_device));
  return result;
};

